<?php
declare(strict_types=1);
require_once __DIR__.'/config/communications_step21.php';
$error=null;$msg=null;$rows=[];
try{$pdo=business_db();comm_step21_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=comm_step21_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){comm_step21_save_channel($pdo,$orgId,(string)$_POST['channel'],(string)$_POST['provider_mode'],(string)$_POST['sender_label'],(int)$user['id']);$msg='Channel setting saved. No secret was stored in the database.';}$s=$pdo->prepare("SELECT * FROM communication_channel_settings WHERE organization_id=? AND channel<>'in_app' ORDER BY FIELD(channel,'email','whatsapp','sms')");$s->execute([$orgId]);foreach($s->fetchAll() as $r){$r['runtime']=comm_step21_channel_runtime($r);$rows[]=$r;}}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Communication Channels - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="communication_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Channel & Provider Readiness</small></span></a><div class="os-top-actions"><a class="os-btn" href="communication_templates.php">Templates</a><a class="os-btn primary" href="communication_center.php">Communications</a></div></div></header><main class="os-main" style="max-width:1180px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">STEP 21 • CHANNEL SETTINGS</div><h1>No provider credentials are stored here.</h1><p>Choose Disabled, Manual or generic Webhook Relay mode. In webhook mode the endpoint/token come only from the named server environment variables.</p></section><?php if($error):?><div class="pp-alert bad"><?=comm_step21_h($error)?></div><?php endif;?><?php if($msg):?><div class="pp-alert good"><?=comm_step21_h($msg)?></div><?php endif;?><section class="s10-grid" style="margin-top:14px"><?php foreach($rows as $r):$rt=$r['runtime'];?><article class="s10-card s10-span-4"><div class="os-title-row"><div><h2><?=comm_step21_h(strtoupper((string)$r['channel']))?></h2><p><?=comm_step21_h((string)$r['provider_mode'])?> mode</p></div><span class="pp-badge <?=((int)$r['is_enabled']===1)?'':'warn'?>"><?=((int)$r['is_enabled']===1)?'ENABLED':'OFF'?></span></div><form method="post" class="pp-form"><input type="hidden" name="channel" value="<?=comm_step21_h($r['channel'])?>"><label class="pp-field"><span>Provider Mode</span><select name="provider_mode"><option value="disabled" <?=$r['provider_mode']==='disabled'?'selected':''?>>Disabled</option><option value="manual" <?=$r['provider_mode']==='manual'?'selected':''?>>Manual App Handoff</option><option value="webhook" <?=$r['provider_mode']==='webhook'?'selected':''?>>Generic Webhook Relay</option></select></label><label class="pp-field"><span>Sender Label</span><input name="sender_label" maxlength="190" value="<?=comm_step21_h($r['sender_label'])?>"></label><button class="os-btn primary">Save</button></form><div class="pp-source" style="margin-top:12px"><div><b>Webhook URL env</b><small><?=comm_step21_h($r['webhook_url_env'])?></small></div><span class="pp-badge <?=($rt['url_configured']??false)?'':'warn'?>"><?=($rt['url_configured']??false)?'SET':'NOT SET'?></span></div><div class="pp-source"><div><b>Webhook token env</b><small><?=comm_step21_h($r['webhook_token_env'])?></small></div><span class="pp-badge <?=($rt['token_configured']??false)?'':'warn'?>"><?=($rt['token_configured']??false)?'SET':'NOT SET'?></span></div></article><?php endforeach;?></section><div class="os-footer-note"><strong>Webhook relay contract:</strong> STEP 21 sends JSON containing channel, recipient, recipient_name, subject, body, idempotency_key and sender_label. Provider-specific transformation belongs in your private relay, not this repository.</div></main></body></html>